using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// Set up options with the default reflection-based resolver
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Get strongly-typed JsonTypeInfo<T> — no manual cast needed.
//    The generic overload returns JsonTypeInfo<T> directly.
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");
Console.WriteLine($"  Kind           : {personInfo.Kind}");
Console.WriteLine($"  Properties     : {personInfo.Properties.Count}");

// Demonstrate it works for serialization
var json = JsonSerializer.Serialize(new Person("Alice", 30), personInfo);
Console.WriteLine($"  Serialized     : {json}");

// 2) Probe whether metadata is available WITHOUT throwing.
//    TryGetTypeInfo returns false instead of throwing if the type isn't resolvable.
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? found))
{
    Console.WriteLine($"\nTryGetTypeInfo(Person) => true  (Kind={found!.Kind})");
}

// Now try a type the resolver can't handle (an open generic):
if (!options.TryGetTypeInfo(typeof(List<>), out _))
{
    Console.WriteLine("TryGetTypeInfo(List<>) => false  (no exception thrown)");
}

public record Person(string Name, int Age);
EOF

